package ar

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"strconv"
	"time"
)

const (
	headerSize   = 60
	globalHeader = "!<arch>\n"
	headerEnd    = "`\n"
)

var (
	// ErrInvalidHeader is returned if the archive or a member header is malformed.
	ErrInvalidHeader = errors.New("ar: invalid header")
	// ErrWriteTooLong is returned if more bytes are written than the header announced.
	ErrWriteTooLong = errors.New("ar: write too long")
)

// Header describes a single archive member.
type Header struct {
	Name    string
	ModTime time.Time
	Uid     int
	Gid     int
	Mode    int64
	Size    int64
}

// Reader reads the members of an ar archive.
type Reader struct {
	r       io.Reader
	started bool
	nb      int64
	pad     int64
}

// NewReader returns a Reader reading from r. The global header is checked on the first call to Next.
func NewReader(r io.Reader) *Reader {
	return &Reader{r: r}
}

func trimField(b []byte) string {
	return string(bytes.TrimRight(b, " "))
}

func parseNumeric(b []byte) (int64, error) {
	s := trimField(b)
	if s == "" {
		return 0, nil
	}
	return strconv.ParseInt(s, 10, 64)
}

// Next advances to the next member and returns its header. It returns io.EOF at the end of the archive.
func (rd *Reader) Next() (*Header, error) {
	if !rd.started {
		buf := make([]byte, len(globalHeader))
		if _, err := io.ReadFull(rd.r, buf); err != nil {
			if err == io.ErrUnexpectedEOF {
				return nil, ErrInvalidHeader
			}
			return nil, err
		}
		if string(buf) != globalHeader {
			return nil, ErrInvalidHeader
		}
		rd.started = true
	}

	if skip := rd.nb + rd.pad; skip > 0 {
		if _, err := io.CopyN(io.Discard, rd.r, skip); err != nil {
			return nil, err
		}
	}
	rd.nb, rd.pad = 0, 0

	buf := make([]byte, headerSize)
	if _, err := io.ReadFull(rd.r, buf); err != nil {
		return nil, err
	}
	if string(buf[58:60]) != headerEnd {
		return nil, ErrInvalidHeader
	}

	hdr := &Header{Name: trimField(buf[0:16])}

	modTime, err := parseNumeric(buf[16:28])
	if err != nil {
		return nil, fmt.Errorf("%w: mtime", ErrInvalidHeader)
	}
	hdr.ModTime = time.Unix(modTime, 0)

	uid, err := parseNumeric(buf[28:34])
	if err != nil {
		return nil, fmt.Errorf("%w: uid", ErrInvalidHeader)
	}
	hdr.Uid = int(uid)

	gid, err := parseNumeric(buf[34:40])
	if err != nil {
		return nil, fmt.Errorf("%w: gid", ErrInvalidHeader)
	}
	hdr.Gid = int(gid)

	if mode := trimField(buf[40:48]); mode != "" {
		if hdr.Mode, err = strconv.ParseInt(mode, 8, 64); err != nil {
			return nil, fmt.Errorf("%w: mode", ErrInvalidHeader)
		}
	}

	size, err := parseNumeric(buf[48:58])
	if err != nil || size < 0 {
		return nil, fmt.Errorf("%w: size", ErrInvalidHeader)
	}
	hdr.Size = size

	rd.nb = size
	rd.pad = size % 2
	return hdr, nil
}

// Read reads from the current member.
func (rd *Reader) Read(b []byte) (int, error) {
	if rd.nb == 0 {
		return 0, io.EOF
	}
	if int64(len(b)) > rd.nb {
		b = b[:rd.nb]
	}
	n, err := rd.r.Read(b)
	rd.nb -= int64(n)
	return n, err
}

// Writer writes an ar archive.
type Writer struct {
	w  io.Writer
	nb int64
}

// NewWriter returns a Writer writing to w.
func NewWriter(w io.Writer) *Writer {
	return &Writer{w: w}
}

// WriteGlobalHeader writes the archive magic.
func (aw *Writer) WriteGlobalHeader() error {
	_, err := io.WriteString(aw.w, globalHeader)
	return err
}

func padded(s string, n int) string {
	return s + string(bytes.Repeat([]byte{' '}, n-len(s)))
}

// WriteHeader writes a member header; the member content must be written with Write afterwards.
func (aw *Writer) WriteHeader(hdr *Header) error {
	if hdr.Size < 0 || len(hdr.Name) > 16 {
		return ErrInvalidHeader
