		err = ErrWriteTooLong
	}
	n, werr := aw.w.Write(b)
	aw.nb -= int64(n)
	if werr != nil {
		return n, werr
	}
	if len(b)%2 == 1 {
		if _, werr = aw.w.Write([]byte{'\n'}); werr != nil {
			return n, werr
		}
	}
	return n, err
}
