package ar

import (
	"bytes"
	"io"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestRoundTrip(t *testing.T) {
	var buf bytes.Buffer
	aw := NewWriter(&buf)
	require.NoError(t, aw.WriteGlobalHeader())
	files := [][2]string{{"a.txt", "odd"}, {"control.tar.gz", "even"}}
	for _, f := range files {
		require.NoError(t, aw.WriteHeader(&Header{Name: f[0], Mode: 0o600, Size: int64(len(f[1]))}))
		_, err := aw.Write([]byte(f[1]))
		require.NoError(t, err)
	}

	r := NewReader(&buf)
	for _, f := range files {
		hdr, err := r.Next()
		require.NoError(t, err)
		assert.Equal(t, f[0], hdr.Name)
		content, err := io.ReadAll(r)
		require.NoError(t, err)
		assert.Equal(t, f[1], string(content))
	}
	_, err := r.Next()
	assert.ErrorIs(t, err, io.EOF)
}

func TestNegativeSize(t *testing.T) {
	data := globalHeader + padded("x", 16) + padded("0", 12) + padded("0", 6) + padded("0", 6) + padded("100644", 8) + padded("-5", 10) + headerEnd
	_, err := NewReader(bytes.NewBufferString(data)).Next()
	assert.ErrorIs(t, err, ErrInvalidHeader)
}

func TestInvalidMagic(t *testing.T) {
	_, err := NewReader(bytes.NewBufferString("not an archive at all")).Next()
	assert.ErrorIs(t, err, ErrInvalidHeader)
}
EOF
